  "george fourcade": "chanteur de séga et écrivain réunionnais né à Saint-Denis ( nord de la réunion et capitale de l'île) en juillet 1884, décéde à Saint-Denis en décembre 1962. Surnommé, le Barbe créole.Travailllant comme agent de la perception des impôts, il décide de prendre des cours de solfège. Georges Fourcade entre à la société des auteurs\"SACD\"= (Société des auteurs et compositeurs dramatiques) fondée en 1777 par Beaumarchais. Îl écrit P'tite Fleur Aimée, qui est l\"un des principaux titres musicaux de la Réunion. Défenseur de la langue créole (kréol). 1928 il publi Z\"histoires la caze et les pièces de théâtre Coq Auguste et Z\"affaire Coco. Introduction des zhistoires la caze (case) ;\"Met zot l\"orgueil de coté, allons parle rien que créole. l'a point malher là-deans et allon fêter, non seulement not patois créole,mais encore et toujour, not musique créole\"",
