  "maloya": "musique Tradionnel de la Réunion il est l'héritier des chants des esclaves. Le terme « maloya » a plusieurs significations suivant les dialectes de l'Afrique de l'Est. Au Mozambique, maloya signifie : incantation, sorcellerie ; au Zimbabwe : grand sorcier ; en Bambara : honte, et à Madagascar \"Maloy Aho\" veut dire : \"parler, dégoiser, dire ce que l'on a à dire\". Dans de nombreux dialectes africains, il signifierait \"peine, douleur, mal-être\".À la fin des années 1950 le maloya était interdit par l'administration coloniale, car cette dernière refuse le droit d'expression au peuple réunionnais de peur de voir grandir l'idée d'une indépendance. Il est donc joué de manière clandestine dans des lieux secrets, tels que dans des champs de canne à sucre loin des habitations. Le 1er octobre 2009 Le maloya est classé au Patrimoine culturel immatériél de l'humanité de l'UNESCO | du malgache \"malahelo\" qui signifie parler | Danse",
